AXION.applyI18n = () => {
  const lang = (AXION.settings && AXION.settings.lang) || 'en';
  document.querySelectorAll('[data-i18n]').forEach(el => { const k=el.getAttribute('data-i18n'); if (el.tagName==='INPUT'||el.tagName==='TEXTAREA') el.placeholder=AXION.t(k); else el.textContent=AXION.t(k); });
  document.querySelectorAll('[data-i18n-title]').forEach(el => { el.title=AXION.t(el.getAttribute('data-i18n-title')); });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => { el.placeholder=AXION.t(el.getAttribute('data-i18n-placeholder')); });
  document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el => { const raw=el.placeholder.trim(); const translated=lang==='id'?AXION.I18N_TEXT_MAP[raw]:AXION.I18N_TEXT_MAP_EN[raw]; if(translated)el.placeholder=translated; });
  // Translate authored UI text nodes outside messages, user files, and Markdown content.
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  const nodes=[]; let n; while((n=walker.nextNode())) nodes.push(n);
  for(const node of nodes){
    const el=node.parentElement; if(!el || el.closest('[data-i18n],script,style,textarea,input,pre,code,.chat,.msg,.md,.artifact-card,.canvas-card,.library-file-name,.workspace-panel')) continue;
    const raw=node.nodeValue, key=raw.trim(); if(!key) continue;
    const translated=lang==='id' ? AXION.I18N_TEXT_MAP[key] : AXION.I18N_TEXT_MAP_EN[key];
    if(translated) node.nodeValue=raw.replace(key,translated);
  }
  if (document.documentElement) document.documentElement.lang=lang;
};
